import java.util.*;

class Solution {
    public int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        res[0] = 1;
        for (int i = 1; i < n; i++) res[i] = res[i - 1] * nums[i - 1]; // product of everything on the left
        int suffix = 1;
        for (int i = n - 1; i >= 0; i--) {
            res[i] *= suffix;     // times product of everything on the right
            suffix *= nums[i];
        }
        return res;
    }
}

