function productExceptSelf(nums) {
  const n = nums.length, out = new Array(n); let p = 1;
  for (let i = 0; i < n; i++) { out[i] = p; p *= nums[i]; }
  p = 1;
  for (let i = n - 1; i >= 0; i--) { out[i] = (out[i] * p) || 0; p *= nums[i]; }
  return out;
}
